This is the preferred method for setting the menu item icon as it provides type safety and better control over image handling.

**Example**

```cpp
// Using file path
auto icon = Image::FromFile("/path/to/icon.png");
item->SetIcon(icon);

// Using base64 data
auto icon = Image::FromBase64("data:image/png;base64,iVBORw0KGgo...");
item->SetIcon(icon);

// Using system icon
auto icon = Image::FromSystemIcon("folder");
item->SetIcon(icon);

// Clear icon
item->SetIcon(nullptr);
```

